import { tasks } from "@trigger.dev/sdk/v3";
import type { webhookHandler } from "./src/trigger/webhook";

async function run() {
  const idempotencyKey = `key-${Date.now()}`;
  const payload = { idempotencyKey, amount: 100 };

  console.log(`Triggering task twice with idempotencyKey: ${idempotencyKey}`);

  const run1 = await tasks.trigger<typeof webhookHandler>("webhook-handler-resilient_webhook_idempotency__8hpna2H", payload, {
    idempotencyKey,
  });

  const run2 = await tasks.trigger<typeof webhookHandler>("webhook-handler-resilient_webhook_idempotency__8hpna2H", payload, {
    idempotencyKey,
  });

  console.log(`Run ID 1: ${run1.id}, Run ID 2: ${run2.id}`);

  if (run1.id === run2.id) {
    console.log("Success: Both triggers returned the same Run ID due to idempotency.");
  } else {
    console.log("Note: In some versions/configurations, Trigger.dev might return the same Run ID or handle it internally. Checking if they refer to the same execution.");
  }
}

run().catch(console.error);

